{
  "name": "cache-demo",
  "version": "1.0.0",
  "private": true,
  "description": "Turborepo cache demonstration example",
  "workspaces": [
    "packages/*"
  ],
  "scripts": {
    "build": "turbo run build",
    "lint": "turbo run lint",
    "test": "turbo run test"
  },
  "devDependencies": {
    "turbo": "latest",
    "typescript": "^5.0.0"
  },
  "packageManager": "npm@10.0.0"
}

export function add(a: number, b: number): number {
  return a + b;
}

export function subtract(a: number, b: number): number {
  return a - b;
}

export function multiply(a: number, b: number): number {
  return a * b;
}

export const VERSION = '1.0.0';

import { add, multiply } from '@cache-demo/core';

export function square(n: number): number {
  return multiply(n, n);
}

export function increment(n: number): number {
  return add(n, 1);
}

export function sum(numbers: number[]): number {
  return numbers.reduce((acc, n) => add(acc, n), 0);
}

import { add, VERSION } from '@cache-demo/core';
import { square, sum } from '@cache-demo/utils';

export function main(): void {
  console.log(`Cache Demo App v${VERSION}`);

  const a = 5;
  const b = 3;

  console.log(`${a} + ${b} = ${add(a, b)}`);
  console.log(`${a}² = ${square(a)}`);
  console.log(`Sum of [1,2,3,4,5] = ${sum([1, 2, 3, 4, 5])}`);
}

if (require.main === module) {
  main();
}

